window.zadaniya_elements={lib:{},assets:[],shapes:{},setup:function(h){
const n=h.MovieClip,e=h.Container,a=h.Sprite,z=h.Text,A=h.Graphics;

const mkBtn=(lbl,w,ht,fill,bord,tc)=>{
  fill=fill||0x1a3a0a;bord=bord||0x3a7a1a;tc=tc||'#90d040';
  const bg=new A();bg.beginFill(fill,1);bg.lineStyle(1,bord);bg.drawRoundedRect(0,0,w,ht,4);bg.endFill();
  const t=new z(lbl,{fontFamily:'Southbank LT',fontSize:12,fontWeight:'bold',fill:tc,align:'center'});
  t.anchor.set(0.5,0.5);t.x=w/2;t.y=ht/2;
  const c=new e();c.addChild(bg,t);c.interactive=true;c.buttonMode=true;
  c.on('mouseover',()=>bg.tint=0xddeecc);c.on('mouseout',()=>bg.tint=0xffffff);
  c._bg=bg;c._txt=t;return c;
};

// ── Карточка задания ───────────────────────────────────────────────
zadaniya_elements.lib.Task_card=class extends e{
  constructor(){
    super();
    this.bg_mc=new A();this._drawBg('daily',false);this.addChild(this.bg_mc);
    // Иконка
    const ic=new z('',{fontFamily:'Arial',fontSize:38,align:'center'});ic.anchor.set(0.5,0.5);ic.x=46;ic.y=44;this[ic.name='icon_txt']=ic;this.addChild(ic);
    // Тип бейдж
    const tbg=new A();tbg.beginFill(0x1a3a00,1);tbg.lineStyle(1,0x3a7a10);tbg.drawRoundedRect(0,0,70,18,3);tbg.endFill();tbg.x=10;tbg.y=6;
    const tt=new z('',{fontFamily:'Southbank LT',fontSize:9,fontWeight:'bold',fill:'#80c030',align:'center'});tt.anchor.set(0.5,0.5);tt.x=35;tt.y=9;
    const tw=new e();tw.addChild(tbg,tt);this[tt.name='type_txt']=tt;this[tw.name='type_badge']=tw;this.addChild(tw);
    // Название
    const nt=new z('',{fontFamily:'Southbank LT',fontSize:15,fontWeight:'bold',fill:'#b8d840'});nt.x=92;nt.y=10;this[nt.name='name_txt']=nt;this.addChild(nt);
    // Описание
    const dt=new z('',{fontFamily:'Arial',fontSize:11,fill:'#5a7a3a',wordWrap:true,wordWrapWidth:480});dt.x=92;dt.y=32;this[dt.name='desc_txt']=dt;this.addChild(dt);
    // Прогресс бар
    const pbg=new A();pbg.beginFill(0x060e04,1);pbg.drawRoundedRect(0,0,580,8,2);pbg.endFill();pbg.x=92;pbg.y=64;this.addChild(pbg);
    this.prog_fill=new A();this.prog_fill.beginFill(0x50a020,1);this.prog_fill.drawRoundedRect(0,0,580,8,2);this.prog_fill.endFill();this.prog_fill.x=92;this.prog_fill.y=64;
    this[this.prog_fill.name='prog_bar']=this.prog_fill;this.addChild(this.prog_fill);
    const pt=new z('',{fontFamily:'Southbank LT',fontSize:10,fill:'#4a6a2a'});pt.x=92;pt.y=76;this[pt.name='prog_txt']=pt;this.addChild(pt);
    // Награда
    const rt=new z('',{fontFamily:'Southbank LT',fontSize:12,fill:'#c8a030'});rt.x=700;rt.y=30;this[rt.name='reward_txt']=rt;this.addChild(rt);
    // Кнопка забрать
    const clm=mkBtn('ЗАБРАТЬ',110,36,0x1e4a00,0x4a9a10,'#a0e040');clm.x=1040;clm.y=20;this[clm.name='butt_claim']=clm;this.addChild(clm);
    // Бейдж выполнено
    const dw=new e();
    const dbg=new A();dbg.beginFill(0x1a3a00,1);dbg.lineStyle(1,0x4a8a10);dbg.drawRoundedRect(0,0,100,36,4);dbg.endFill();
    const dt2=new z('✅ СДАНО',{fontFamily:'Southbank LT',fontSize:12,fontWeight:'bold',fill:'#60c020',align:'center'});dt2.anchor.set(0.5,0.5);dt2.x=50;dt2.y=18;
    dw.addChild(dbg,dt2);dw.x=1040;dw.y=20;dw.visible=false;this[dw.name='done_badge']=dw;this.addChild(dw);
  }
  _drawBg(type,done){
    const cols={daily:0x1a3a0a, weekly:0x2a1a3a, special:0x3a2a00};
    const bordr={daily:0x3a7a1a, weekly:0x6a3a7a, special:0x9a6a10};
    const col=cols[type]||cols.daily;const brd=bordr[type]||bordr.daily;
    this.bg_mc.clear();
    this.bg_mc.beginFill(done?0x0c1e06:0x080e05, done?0.97:0.92);
    this.bg_mc.lineStyle(done?2:1, done?0x3a7018:brd, done?0.8:0.6);
    this.bg_mc.drawRoundedRect(0,0,1160,92,6);this.bg_mc.endFill();
  }
  setData(type,done,prog,maxProg){
    const typeLabels={daily:'ДНЕВНОЕ',weekly:'НЕДЕЛЬНОЕ',special:'ОСОБОЕ'};
    const typeColors={daily:'#80c030',weekly:'#c060e0',special:'#e0a020'};
    this.type_txt.text=typeLabels[type]||'ЗАДАНИЕ';
    this.type_txt.style.fill=typeColors[type]||'#80c030';
    this._drawBg(type,done);
    this.done_badge.visible=done;
    this.butt_claim.visible=!done&&prog>=maxProg;
    this.prog_bar.visible=!done;
    this.prog_txt.visible=!done;
    if(!done){
      this.prog_bar.scale.x=Math.min(1,prog/Math.max(1,maxProg));
      this.prog_txt.text=prog+' / '+maxProg;
    }
  }
};

// ── Таймер сброса ──────────────────────────────────────────────────
zadaniya_elements.lib.Reset_timer=class extends e{
  constructor(){
    super();
    const bg=new A();bg.beginFill(0x080e05,0.9);bg.lineStyle(1,0x1a3010,0.6);bg.drawRoundedRect(0,0,320,40,4);bg.endFill();this.addChild(bg);
    const lbl=new z('Сброс через:',{fontFamily:'Southbank LT',fontSize:11,fill:'#4a6a2a'});lbl.x=14;lbl.y=12;this.addChild(lbl);
    const tt=new z('00:00:00',{fontFamily:'Southbank LT',fontSize:16,fontWeight:'bold',fill:'#90c040'});tt.x=130;tt.y=9;this[tt.name='time_txt']=tt;this.addChild(tt);
  }
};

// ── Прогресс-бар дня ──────────────────────────────────────────────
zadaniya_elements.lib.Day_progress=class extends e{
  constructor(){
    super();
    const lbl=new z('ВЫПОЛНЕНО ДНЕВНЫХ:',{fontFamily:'Southbank LT',fontSize:11,fill:'#4a6a2a',letterSpacing:1});lbl.x=0;lbl.y=0;this.addChild(lbl);
    const pbg=new A();pbg.beginFill(0x060e04,1);pbg.drawRoundedRect(0,0,600,10,3);pbg.endFill();pbg.y=24;this.addChild(pbg);
    this.fill=new A();this.fill.beginFill(0x60b820,1);this.fill.drawRoundedRect(0,0,600,10,3);this.fill.endFill();this.fill.y=24;
    this[this.fill.name='fill']=this.fill;this.addChild(this.fill);
    const ct=new z('0 / 0',{fontFamily:'Southbank LT',fontSize:12,fontWeight:'bold',fill:'#90c040'});ct.x=610;ct.y=18;this[ct.name='count_txt']=ct;this.addChild(ct);
  }
  setProgress(done,total){
    this.fill.scale.x=Math.min(1,done/Math.max(1,total));
    this.count_txt.text=done+' / '+total;
  }
};

// ── Главное окно Заданий ───────────────────────────────────────────
zadaniya_elements.lib.Zadaniya_win=class extends e{
  constructor(){
    super();
    const wb=new A();wb.beginFill(0x060c04,0.97);wb.lineStyle(2,0x284a18,0.9);wb.drawRoundedRect(0,0,1200,524,6);wb.endFill();this.addChild(wb);
    const hb=new A();hb.beginFill(0x081802,1);hb.drawRect(2,2,1196,42);hb.endFill();
    const hl=new A();hl.lineStyle(1,0x284a18,0.5);hl.moveTo(2,45);hl.lineTo(1198,45);this.addChild(hb,hl);
    const ttl=new z('ЗАДАНИЯ',{fontFamily:'Southbank LT',fontSize:18,fontWeight:'bold',fill:'#b8d840',letterSpacing:5,dropShadow:true,dropShadowDistance:2,dropShadowColor:'#000'});ttl.x=20;ttl.y=12;this.addChild(ttl);
    const cbg=new A();cbg.beginFill(0x3a1010,1);cbg.lineStyle(1,0x882222);cbg.drawRoundedRect(0,0,30,30,4);cbg.endFill();
    const ctx=new z('×',{fontFamily:'Arial',fontSize:22,fill:'#cc4444'});ctx.anchor.set(0.5,0.5);ctx.x=15;ctx.y=15;
    const cl=new e();cl.addChild(cbg,ctx);cl.x=1162;cl.y=7;cl.interactive=true;cl.buttonMode=true;cl.on('mouseover',()=>cbg.tint=0xddaaaa);cl.on('mouseout',()=>cbg.tint=0xffffff);
    this[cl.name='butt_close']=cl;this.addChild(cl);
    // Таймер и прогресс дня
    const timer=new zadaniya_elements.lib.Reset_timer();timer.x=840;timer.y=8;this[timer.name='reset_timer']=timer;this.addChild(timer);
    const dayp=new zadaniya_elements.lib.Day_progress();dayp.x=20;dayp.y=52;this[dayp.name='day_progress']=dayp;this.addChild(dayp);
    // 5 карточек заданий
    const cards=new e();cards.x=20;cards.y=96;
    for(let i=0;i<5;i++){
      const c=new zadaniya_elements.lib.Task_card();c.y=i*(92+6);cards['card_'+i]=c;cards.addChild(c);
    }
    this[cards.name='task_cards']=cards;this.addChild(cards);
  }
};

zadaniya_elements.lib.zadaniya_elements=class extends n{
  constructor(){super({duration:1,framerate:30});const b=new zadaniya_elements.lib.Zadaniya_win();this[b.name='zadaniya_win']=b;this.addChild(b);}
};
zadaniya_elements.stage=zadaniya_elements.lib.zadaniya_elements}};
